const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Helpers
    const getInfo = (obj) => new Promise((res, rej) => obj.getInfo(res, rej));

    // 1. Geometry & Water Mask (Lake Elton, Russia)
    const lakeCenter = ee.Geometry.Point([46.70, 49.13]);
    const roi = lakeCenter.buffer(12000).bounds();
    const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence').clip(roi);
    const waterMask = gsw.gt(50).selfMask(); // persistent water >50%
    const waterOnes = ee.Image(1).updateMask(waterMask);
    const waterPix = await getInfo(waterOnes.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: 1000,
      maxPixels: 1e9
    }));
    const waterPixCount = waterPix ? waterPix.constant || 0 : 0;
    console.log(`Water baseline pixels (1km): ${waterPixCount}`);

    async function yearStats(year) {
      const startMS = ee.Date.fromYMD(year, 5, 1);
      const endMS = ee.Date.fromYMD(year, 9, 30);
      const startFB = ee.Date.fromYMD(year, 1, 1);
      const endFB = ee.Date.fromYMD(year, 12, 31);

      function maskScaleL57(image) {
        const qa = image.select('QA_PIXEL');
        const mask = qa.bitwiseAnd(1 << 3).eq(0) // cloud
          .and(qa.bitwiseAnd(1 << 4).eq(0)) // shadow
          .and(qa.bitwiseAnd(1 << 5).eq(0)) // snow
          .and(qa.bitwiseAnd(1 << 1).eq(0)); // dilated cloud
        const scaled = image.select(['SR_B1', 'SR_B2', 'SR_B3'])
          .multiply(0.0000275).add(-0.2)
          .rename(['blue', 'green', 'red']);
        return scaled.updateMask(mask);
      }

      const l5_ms = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterDate(startMS, endMS).filterBounds(roi).map(maskScaleL57);
      const l7_ms = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterDate(startMS, endMS).filterBounds(roi).map(maskScaleL57);
      let col = l5_ms.merge(l7_ms);
      let nImg = await getInfo(col.size());
      let usedWindow = 'May-Sep';
      if (!nImg || nImg === 0) {
        const l5_fb = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
          .filterDate(startFB, endFB).filterBounds(roi).map(maskScaleL57);
        const l7_fb = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
          .filterDate(startFB, endFB).filterBounds(roi).map(maskScaleL57);
        col = l5_fb.merge(l7_fb);
        nImg = await getInfo(col.size());
        usedWindow = 'Year';
      }
      return { col, nImg, usedWindow };
    }

    // Get stats for both years
    const y2004 = await yearStats(2004);
    const y2009 = await yearStats(2009);

    if ((y2004.nImg || 0) === 0 || (y2009.nImg || 0) === 0) {
      console.log('One or both years have 0 images after fallback.');
      console.log('C1');
      return;
    }

    function visComposite(col) {
      const visCol = col.map(img => {
        const visMean = img.select(['blue', 'green', 'red']).reduce(ee.Reducer.mean()).rename('vis_mean');
        return visMean;
      });
      return visCol.median();
    }

    async function summarize(year, info) {
      const comp = visComposite(info.col).updateMask(waterMask);
      const stats = await getInfo(comp.reduceRegion({
        reducer: ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true }),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }));
      const mean = stats ? stats.vis_mean_mean : null;
      const count = stats ? stats.vis_mean_count : 0;
      const cover = waterPixCount > 0 ? (100 * (count || 0) / waterPixCount) : 0;
      console.log(`${year} ${info.usedWindow} imgs: ${info.nImg}, validPx: ${count || 0}, cover: ${cover.toFixed(1)}%, visMean: ${mean !== null ? mean.toFixed(4) : 'null'}`);
      return { mean, count };
    }

    const s2004 = await summarize(2004, y2004);
    const s2009 = await summarize(2009, y2009);

    if ((s2004.count || 0) === 0 || (s2009.count || 0) === 0) {
      console.log('C2');
      return;
    }

    const m2004 = s2004.mean;
    const m2009 = s2009.mean;
    if (m2004 === null || m2009 === null || !isFinite(m2004) || !isFinite(m2009)) {
      console.log('C3');
      return;
    }

    // Final Answer: Did reflectance increase from 2004 to 2009?
    console.log(m2009 > m2004 ? 'A' : 'B');
  } catch (e) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
